export function useVotingStatus(locks) {
  const account = useAccount();
  const chainId = account.chainId || UniverseChainId.AbstractTestnet;
  const provider = useEthersProvider({ chainId });
  const { epochStart } = useVoterReads();
  const votingStatusQuery = useQuery({
    queryKey: ["voting-status", locks?.map((l) => l.id).join(","), chainId, epochStart],
    queryFn: async () => {
      if (!locks || locks.length === 0) return [];
      try {
        if (!provider) {
          throw new Error("Provider not available");
        }
        const voterAddress = getContractAddress(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
        const voterAbi = getContractAbi(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
        if (!voterAddress || !voterAbi) {
          throw new Error("Voter contract not available");
        }
        const multicall = new Contract(MULTICALL3_ADDRESS, MULTICALL3_ABI, provider);
        const voter = new Contract(voterAddress, voterAbi, provider);
        console.log("=== VOTING STATUS DEBUG SESSION START ===");
        console.log("Current timestamp:", (/* @__PURE__ */ new Date()).toISOString());
        console.log("Checking voting status for locks:", locks.map((l) => l.id));
        console.log("Lock details:", locks.map((l) => ({
          id: l.id,
          owner: l.owner,
          amount: l.amount,
          votingPower: l.votingPower,
          lockEnd: l.lockEnd,
          permanent: l.permanent
        })));
        console.log("=== EPOCH TIMING DEBUG ===");
        console.log("Current epoch start timestamp:", epochStart);
        console.log("Current epoch start date:", epochStart ? new Date(epochStart * 1e3).toISOString() : "undefined");
        const currentTime = Date.now() / 1e3;
        console.log("Current timestamp:", currentTime);
        console.log("Current date:", new Date(currentTime * 1e3).toISOString());
        if (epochStart) {
          const timeIntoEpoch = currentTime - epochStart;
          const daysIntoEpoch = timeIntoEpoch / (24 * 60 * 60);
          const hoursIntoEpoch = timeIntoEpoch / (60 * 60);
          console.log("Time since epoch start:", {
            seconds: timeIntoEpoch,
            hours: hoursIntoEpoch.toFixed(2),
            days: daysIntoEpoch.toFixed(2)
          });
          const expectedEpochLength = 7 * 24 * 60 * 60;
          const nextExpectedEpochStart = epochStart + expectedEpochLength;
          console.log("Expected next epoch start:", new Date(nextExpectedEpochStart * 1e3).toISOString());
          if (daysIntoEpoch > 7) {
            console.log("\u{1F6A8} WARNING: More than 7 days since epoch start - voting may need reset!");
          }
        }
        console.log("==========================");
        console.log("Using addresses:", {
          multicall: MULTICALL3_ADDRESS,
          voter: voterAddress,
          provider: !!provider,
          chainId,
          epochStart
        });
        const votingCalls = locks.map((lock) => ({
          target: voterAddress,
          callData: voter.interface.encodeFunctionData("lastVoted", [BigInt(lock.id)])
        }));
        console.log("Prepared voting calls using lastVoted method:");
        votingCalls.forEach((call, index) => {
          console.log(`Lock ${locks[index].id}: target=${call.target}, method=lastVoted(${locks[index].id})`);
        });
        const batchSize = 50;
        const allResults = [];
        for (let i = 0; i < votingCalls.length; i += batchSize) {
          const batch = votingCalls.slice(i, i + batchSize);
          try {
            const [, returnData] = await multicall.callStatic.aggregate(batch);
            const batchResults = returnData.map((result, index) => {
              try {
                const lockIndex = i + index;
                const lock = locks[lockIndex];
                const decoded = voter.interface.decodeFunctionResult("lastVoted", result);
                const lastVotedTimestamp = Number(decoded[0]);
                const hasVoted = epochStart ? lastVotedTimestamp >= epochStart : false;
                console.log(`=== LOCK VOTING STATUS DETAIL ===`);
                console.log(`Lock ID: ${lock?.id}`);
                console.log(`Lock Owner: ${lock?.owner}`);
                console.log(`Contract call result (raw): ${result}`);
                console.log(`Decoded timestamp: ${decoded[0]} (${lastVotedTimestamp})`);
                console.log(`Last voted date: ${lastVotedTimestamp > 0 ? new Date(lastVotedTimestamp * 1e3).toISOString() : "Never voted"}`);
                console.log(`Current epoch start: ${epochStart} (${epochStart ? new Date(epochStart * 1e3).toISOString() : "undefined"})`);
                console.log(`Has voted this epoch: ${hasVoted}`);
                console.log(`Logic: ${lastVotedTimestamp} >= ${epochStart} = ${hasVoted}`);
                console.log(`Contract method called: voter.lastVoted(${lock?.id})`);
                console.log(`====================================`);
                return hasVoted;
              } catch (error) {
                console.error("Error decoding lastVoted result:", error);
                return false;
              }
            });
            allResults.push(...batchResults);
          } catch (error) {
            console.error("Voting status multicall batch failed:", error);
            console.log("Attempting individual contract calls as fallback...");
            const individualResults = [];
            for (let j = 0; j < batch.length; j++) {
              try {
                const lockIndex = i + j;
                if (lockIndex >= locks.length) break;
                const lock = locks[lockIndex];
                const lastVotedTimestamp = await voter.lastVoted(BigInt(lock.id));
                const lastVotedNumber = Number(lastVotedTimestamp);
                const hasVoted = epochStart ? lastVotedNumber >= epochStart : false;
                console.log(`=== INDIVIDUAL CALL FALLBACK ===`);
                console.log(`Lock ID: ${lock.id}`);
                console.log(`Lock Owner: ${lock.owner}`);
                console.log(`Individual contract call result: ${lastVotedTimestamp}`);
                console.log(`Last voted timestamp: ${lastVotedNumber}`);
                console.log(`Last voted date: ${lastVotedNumber > 0 ? new Date(lastVotedNumber * 1e3).toISOString() : "Never voted"}`);
                console.log(`Current epoch start: ${epochStart}`);
                console.log(`Has voted this epoch: ${hasVoted}`);
                console.log(`Contract method: voter.lastVoted(BigInt(${lock.id}))`);
                console.log(`===============================`);
                individualResults.push(hasVoted);
              } catch (individualError) {
                console.error(`Individual call failed for lock ${locks[i + j]?.id}:`, individualError);
                individualResults.push(false);
              }
            }
            allResults.push(...individualResults);
          }
        }
        const finalResults = locks.map((lock, index) => ({
          tokenId: lock.id,
          hasVoted: allResults[index] || false
        }));
        console.log("=== FINAL VOTING STATUS SUMMARY ===");
        console.log("Total locks processed:", locks.length);
        console.log("Results received:", allResults.length);
        console.log("Final voting status results:", finalResults);
        const votedCount = finalResults.filter((r) => r.hasVoted).length;
        const unvotedCount = finalResults.filter((r) => !r.hasVoted).length;
        console.log("Summary:");
        console.log(`- Locks that have voted: ${votedCount}`);
        console.log(`- Locks that haven't voted: ${unvotedCount}`);
        console.log(`- Total locks: ${finalResults.length}`);
        if (votedCount === finalResults.length && finalResults.length > 0) {
          console.log("\u{1F6A8} ALL LOCKS SHOWING AS VOTED - This may indicate:");
          console.log("1. All locks genuinely voted this epoch (lastVoted >= epochStart)");
          console.log("2. Epoch timing issue - epochStart not updated properly");
          console.log("3. All locks voted in previous epoch and new epoch not started");
          console.log("4. Contract state issue with Voter contract or epoch calculation");
        }
        if (votedCount === 0 && finalResults.length > 0) {
          console.log("\u2705 ALL LOCKS AVAILABLE TO VOTE - Epoch appears to have reset properly");
        }
        console.log("=== VOTING STATUS DEBUG SESSION END ===");
        return finalResults;
      } catch (error) {
        console.error("Failed to check voting status:", error);
        return locks.map((lock) => ({
          tokenId: lock.id,
          hasVoted: false,
          error: "Failed to check voting status"
        }));
      }
    },
    enabled: !!locks && locks.length > 0 && !!chainId && !!provider,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
  return {
    lockStatuses: votingStatusQuery.data || [],
    isLoading: votingStatusQuery.isLoading,
    error: votingStatusQuery.error?.message,
    refetch: votingStatusQuery.refetch
  };
}
export function useLockVotingStatus(tokenId) {
  const locks = tokenId ? [{ id: tokenId }] : void 0;
  const { lockStatuses, isLoading, error } = useVotingStatus(locks);
  return {
    tokenId: tokenId || "",
    hasVoted: lockStatuses[0]?.hasVoted || false,
    isLoading,
    error
  };
}
export const VotingStatusUtils = {
  /**
   * Filter locks that haven't voted yet
   */
  filterUnvotedLocks: (locks, statuses) => {
    const statusMap = new Map(statuses.map((s) => [s.tokenId, s.hasVoted]));
    return locks.filter((lock) => !statusMap.get(lock.id));
  },
  /**
   * Filter locks that have already voted
   */
  filterVotedLocks: (locks, statuses) => {
    const statusMap = new Map(statuses.map((s) => [s.tokenId, s.hasVoted]));
    return locks.filter((lock) => statusMap.get(lock.id));
  },
  /**
   * Get voting status summary
   */
  getVotingStatusSummary: (statuses) => {
    const total = statuses.length;
    const voted = statuses.filter((s) => s.hasVoted).length;
    const unvoted = total - voted;
    return {
      total,
      voted,
      unvoted,
      votedPercentage: total > 0 ? Math.round(voted / total * 100) : 0
    };
  }
};
