"use strict";
import { useState } from "react";
import { ChevronDown } from "react-feather";
import styled from "styled-components";
import { AnimatedPopover, Flex, Popover, Text, styled as UiStyled } from "ui/src";
import { Check, CheckCircleFilled, Plus } from "ui/src/components/icons";
const Checkmark = function() {
  return <Check color={"$greenVibrant"} size={"$icon.12"} />;
};
const PlusSign = function() {
  return <Plus color={"$neutral1"} size={"$icon.12"} />;
};
export default function FilterPools() {
  const [activeFilter, setActiveFilter] = useState("Most Rewarded");
  const ToggleButtons = ["Most Rewarded", "Least Rewarded", "All Pools"];
  const Button = styled.button`
    padding: 8px 12px;
    background-color: transparent;
    border: none;
    cursor: pointer;
    hover {
      color: red;
    }
  `;
  const TextCotainer = UiStyled(Text, {
    variant: "body3",
    color: "$neutral1",
    cursor: "pointer",
    hoverStyle: {
      color: "$accent1"
    }
  });
  return <Flex>
      <Flex
    row
    alignItems="center"
    borderStyle="solid"
    borderWidth={1}
    borderColor="$surface2"
    borderRadius={"$rounded12"}
    $lg={{ display: "none" }}
  >
        {ToggleButtons.map((filter) => <Flex
    key={filter}
    row
    borderLeftWidth={1}
    borderRightWidth={1}
    paddingVertical={"$spacing2"}
    borderColor={"$surface2"}
  >
            <Button onClick={() => setActiveFilter(filter)}>
              <TextCotainer>{filter}</TextCotainer>
              {activeFilter === filter ? <Checkmark /> : <PlusSign />}
            </Button>
          </Flex>)}
      </Flex>

      <MobileFilter options={ToggleButtons} activeFilter={activeFilter} setActiveFilter={setActiveFilter} />
    </Flex>;
}
const MobileFilter = ({
  options,
  activeFilter,
  setActiveFilter
}) => {
  const [isOpen, setIsOpen] = useState(false);
  return <Flex display="none" $lg={{ display: "block" }}>
      <Text variant="body3" color="$neutral2">
        Filter
      </Text>

      <Popover allowFlip onOpenChange={setIsOpen}>
        <Popover.Trigger
    py={"$spacing12"}
    px={"$spacing12"}
    gap={"$gap8"}
    mt={"$spacing8"}
    borderWidth={1}
    borderColor={"$surface3"}
    justifyContent="space-between"
    alignItems="center"
    borderRadius={"$rounded12"}
    cursor="pointer"
  >
          <Flex row gap={"$gap4"} alignItems="center">
            <Text variant="buttonLabel3">{activeFilter}</Text>
            <Flex transform={isOpen ? "rotate(180deg)" : "rotate(0deg)"}>
              <ChevronDown size={16} />
            </Flex>
          </Flex>
        </Popover.Trigger>
        <AnimatedPopover isOpen={isOpen} marginTop={"$spacing8"}>
          <Flex $md={{ pb: "$spacing24" }}>
            {options.map((option) => <Popover.Close key={option} asChild>
                <Flex
    row
    py={"$spacing16"}
    hoverStyle={{ backgroundColor: "$surface2" }}
    cursor="pointer"
    alignItems="center"
    gap={"$gap12"}
    px={"$spacing12"}
    width={"100%"}
    borderRadius={"$rounded12"}
    onPress={() => {
      setActiveFilter(option);
    }}
  >
                  <Text variant="buttonLabel3">{option}</Text>
                  {activeFilter === option && <CheckCircleFilled size={16} />}
                </Flex>
              </Popover.Close>)}
          </Flex>
        </AnimatedPopover>
      </Popover>
    </Flex>;
};
