"use strict";
import { Flex, Text } from "ui/src";
import { useAppDispatch, useAppSelector } from "state/hooks";
import { addPendingVote, removePendingVote, selectPendingVotes } from "state/voting/slice";
export default function PopoverAllVotes({ gauge }) {
  const dispatch = useAppDispatch();
  const pendingVotes = useAppSelector(selectPendingVotes);
  if (!gauge) {
    return <Flex row gap="$gap4" alignItems="center">
        <Text variant="body3" color="$neutral3">
          No gauge
        </Text>
      </Flex>;
  }
  const isSelected = pendingVotes.some((vote) => vote.poolAddress === gauge.pool);
  const handleSelect = () => {
    console.log("PopoverAllVotes handleSelect called", { gauge, isSelected });
    if (isSelected) {
      console.log("Removing pending vote for pool:", gauge.pool);
      dispatch(removePendingVote(gauge.pool));
    } else {
      console.log("Adding pending vote for pool:", gauge.pool);
      dispatch(addPendingVote({
        poolAddress: gauge.pool,
        poolId: gauge.id,
        weight: 1,
        // Set a small weight so it shows up in pending votes
        pool: gauge
      }));
    }
  };
  return <Flex
    row
    gap="$gap4"
    alignItems="center"
    cursor="pointer"
    onPress={handleSelect}
    py="$spacing4"
    px="$spacing8"
    borderRadius="$rounded8"
    backgroundColor={isSelected ? "$accent1" : "$surface2"}
    hoverStyle={{
      backgroundColor: isSelected ? "$accent1Hovered" : "$surface2Hovered"
    }}
  >
      <Text
    variant="body3"
    color={isSelected ? "$surface1" : "$neutral1"}
  >
        {isSelected ? "Selected" : "Select"}
      </Text>
    </Flex>;
}
